10	const SPHINX_BASE_POINTS = 1;
11	const POINTS_PER_EXTRA_TYPE = 2;
12	const FEW_TYPES_POINTS = 1;
13	const MANY_TYPES_THRESHOLD = 3;
14	
15	const containsSphinx = (army: Card[]): boolean =>
16	  army.some((card) => card.monster === SPHINX);
17	
18	const countDistinctTypes = (army: Card[]): number =>
19	  new Set(army.map((card) => card.monster)).size;
20	
21	const pointsForTypes = (types: number): number =>
22	  types > MANY_TYPES_THRESHOLD
23	    ? POINTS_PER_EXTRA_TYPE * (types - MANY_TYPES_THRESHOLD - 1)
24	    : FEW_TYPES_POINTS;
25	
26	export const scoreArmy = (army: Card[]): number => {
27	  if (!containsSphinx(army)) return NO_SPHINX_SCORE;
28	  return SPHINX_BASE_POINTS + pointsForTypes(countDistinctTypes(army));
29	};
